Item.method_code:
const {
	itemTypeName,
	itemId,
	commandFactory
} = options;
const commandAlias = target['command_alias@keyed_name'];
const deleteCommand = commandFactory(commandAlias, {
	...options,
	itemNode: window.item,
});
const disabled = !deleteCommand.canExecute();
const isFixForApplications = ['mpp_ProcessPlan', 'mpp_Operation', 'mpp_Tool', 'Manufacturer Part'].includes(itemTypeName);
const isNew = isFixForApplications ? aras.isNew(window.item) : ArasModules.item.isNew(itemTypeName, itemId);
const hidden = !isNew;

return {
	hidden,
	disabled
};
